public:
 Ocr(){QString path=QCoreApplication::applicationDirPath()+"/../tessdata";if(!QFile::exists(path+"/eng.traineddata")&&!qEnvironmentVariableIsSet("WOW_BUNDLED"))path="/usr/share/tesseract-ocr/5/tessdata";need(QFile::exists(path+"/eng.traineddata"),"The packaged English recognition data is missing. No controls changed.");need(api.Init(path.toUtf8().constData(),"eng",tesseract::OEM_LSTM_ONLY)==0,"Packaged text recognition could not start.");api.SetPageSegMode(tesseract::PSM_SPARSE_TEXT);api.SetVariable("debug_file","/dev/null");}
 QList<Word> readPass(const QImage &input){auto im=input.scaled(input.width()*2,input.height()*2,Qt::IgnoreAspectRatio,Qt::SmoothTransformation).convertToFormat(QImage::Format_RGB888);api.SetImage(im.constBits(),im.width(),im.height(),3,im.bytesPerLine());need(api.Recognize(nullptr)==0,"Screen text could not be recognized.");QList<Word> out,atoms;auto *it=api.GetIterator();if(!it)return out;for(auto level:{tesseract::RIL_TEXTLINE,tesseract::RIL_WORD}){it->Begin();do{int x1,y1,x2,y2;std::unique_ptr<char[]> t(it->GetUTF8Text(level));if(t&&it->BoundingBox(level,&x1,&y1,&x2,&y2)&&it->Confidence(level)>=75){Word word{norm(QString::fromUtf8(t.get())),QRect(x1/2,y1/2,(x2-x1+1)/2,(y2-y1+1)/2),it->Confidence(level)};out.append(word);if(level==tesseract::RIL_WORD)atoms.append(word);}}while(it->Next(level));}delete it;for(int i=0;i<atoms.size();++i){auto phrase=atoms[i];for(int j=i+1;j<qMin(i+6,int(atoms.size()));++j){const auto &next=atoms[j];const auto &previous=atoms[j-1];int height=qMax(previous.box.height(),next.box.height()),gap=next.box.left()-previous.box.right();if(qAbs(next.box.center().y()-previous.box.center().y())>height/2||gap<0||gap>height*2)break;phrase.text+=" "+next.text;phrase.box=phrase.box.united(next.box);phrase.confidence=qMin(phrase.confidence,next.confidence);out.append(phrase);}}return out;}
