    while(window.decision==ControllerFrameSafety::SourceDecision::Future&&timer.elapsed()<5000){checkpoint();QThread::msleep(5);verifyCaptureStream();observedAt=captureNowMs();now=captureRunningTime();window=ControllerFrameSafety::sourceWindow(*segment,GST_BUFFER_PTS(buffer),now,sceneBoundary,frameLease.pts());}
    timing.append(QJsonObject{{"pts",QString::number(GST_BUFFER_PTS(buffer))},{"running_pts",QString::number(window.running)},{"clock_running",QString::number(now)},{"source_age_ns",QString::number(window.age)},{"offset",QString::number(GST_BUFFER_OFFSET(buffer))},{"decision",int(window.decision)}});while(timing.size()>8)timing.removeFirst();
    controllerDiagnostic["capture"]=QJsonObject{{"stage",controllerPhase},{"samples",samples},{"excluded",excluded},{"scene_boundary",QString::number(sceneBoundary)},{"published_pts",QString::number(frameLease.pts())},{"timing",timing}};
    need(window.decision!=ControllerFrameSafety::SourceDecision::Invalid,"Screen source timestamps or clock mapping are invalid. Setup stopped new input.");
