    GstVideoInfo info;auto *caps=gst_sample_get_caps(sample.get());GstVideoFrame mapped;need(caps&&gst_video_info_from_caps(&info,caps)&&gst_video_frame_map(&mapped,&info,buffer,GST_MAP_READ),"Capture frame cannot be read; setup stopped.");
