    need(!owned.isNull()&&qAbs(double(owned.width())/owned.height()-double(desktop.width())/desktop.height())<.02,"Approved monitor geometry differs from the desktop; no input sent.");auto image=owned.scaled(desktop.size(),Qt::IgnoreAspectRatio,Qt::SmoothTransformation);
