QJsonObject factoryEvidence(const QList<Word>&rows){
 const auto notice=norm("This configuration is unique to this controller. To change this, use the gear icon menu above");
 bool shared=false;for(const auto&r:rows)if(r.text.startsWith("this configuration is shared"))shared=true;
 QJsonObject e{{"overview_anchors",false},{"template_marker",false},{"template_label",false},{"unique_notice",false},{"legacy_exact_unique_notice",has(rows,notice)},{"shared_notice",shared},{"eligible",false}};
 try{
  auto view=unique(rows,"View Layout"),edit=unique(rows,"Edit Layout"),quick=unique(rows,"QUICK SETTINGS");
  need(qAbs(view.center().y()-edit.center().y())<=qMax(view.height(),edit.height())&&view.right()<edit.left()&&quick.top()>qMax(view.bottom(),edit.bottom()),"Factory overview anchors are uncertain.");e["overview_anchors"]=true;
  int left=qMax(0,view.left()-200),right=edit.right()+300,top=qMax(0,qMin(view.top(),edit.top())-180);
  QRect card(left,top,right-left,qMin(view.top(),edit.top())-top),caption(left,qMax(view.bottom(),edit.bottom())+1,right-left,quick.top()-qMax(view.bottom(),edit.bottom())-1);
  try{unique(rows,"Using Template:",card);e["template_marker"]=true;}catch(const std::exception&){}
  QList<Word> labels;for(auto r:rows)if((r.text==norm("Gamepad With Joystick Trackpad")||r.text==norm("Gamepad With Mouse Trackpad"))&&card.contains(r.box.center())){r.text="factory-label";labels.append(r);}
  try{unique(labels,"factory-label",card);e["template_label"]=true;}catch(const std::exception&){}
  // The complete fixed notice must be recognized in its own overview row.
  // Steam's trailing shortcut glyph can also be OCR text; it is not part of
  // the sentence. This does not accept a title-only or first-clause match.
  QList<Word> notices;for(auto r:rows)if(r.text.startsWith(notice)&&caption.contains(r.box.center())){r.text="factory-unique-notice";notices.append(r);}
  try{unique(notices,"factory-unique-notice",caption);e["unique_notice"]=true;}catch(const std::exception&){}
  e["eligible"]=e["template_marker"].toBool()&&e["template_label"].toBool()&&e["unique_notice"].toBool()&&!shared;
 }catch(const std::exception&){}
 return e;
}
bool factoryTemplate(const QList<Word>&rows){return factoryEvidence(rows)["eligible"].toBool();}
